DO $$ BEGIN CREATE TABLE public.roles (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version integer NOT NULL DEFAULT 0 CHECK (version >= 0), kind varchar(16) NOT NULL CHECK (kind IN ('preset','custom')), base_role_id uuid REFERENCES public.roles(id), identity_type varchar(16) NOT NULL CHECK (identity_type IN ('company','bureau','agent','school','teacher','student','parent')), org_id uuid REFERENCES public.orgs(id), code varchar(64) NOT NULL, name varchar(64) NOT NULL, data_scope varchar(32) NOT NULL CHECK (data_scope IN ('personal','dept','dept_and_below','all')), default_department varchar(64), remark text, status smallint NOT NULL DEFAULT 1 CHECK (status IN (0,1)), CONSTRAINT roles_kind_org_check CHECK ((kind='preset' AND org_id IS NULL AND base_role_id IS NULL) OR (kind='custom' AND org_id IS NOT NULL AND base_role_id IS NOT NULL))); CREATE UNIQUE INDEX roles_preset_code_unique ON public.roles(code) WHERE kind='preset' AND deleted_at IS NULL; CREATE UNIQUE INDEX roles_org_code_unique ON public.roles(org_id,code) WHERE kind='custom' AND deleted_at IS NULL; CREATE TABLE public.role_grants (role_id uuid NOT NULL REFERENCES public.roles(id) ON DELETE CASCADE, app_code varchar(32) NOT NULL, feature_code varchar(32) NOT NULL, level varchar(16) NOT NULL CHECK (level IN ('none','view','edit','manage','custom')), actions text[], PRIMARY KEY (role_id, app_code, feature_code), FOREIGN KEY (app_code, feature_code) REFERENCES public.features(app_code,code), CONSTRAINT role_grants_actions_check CHECK ((level='custom' AND actions IS NOT NULL) OR (level<>'custom' AND actions IS NULL))); ALTER TABLE public.identity_roles ADD CONSTRAINT identity_roles_role_id_fkey FOREIGN KEY (role_id) REFERENCES public.roles(id) ON DELETE CASCADE; END $$;
